SELECT s1.`c0` AS `g`, s1.`c1` AS `x`, s1.`c2` AS `p`, s1.`c3` AS `n`, s1.`c4` AS `rn` FROM (SELECT s2.`c5` AS `c0`, s2.`c6` AS `c1`, s2.`c7` AS `c2`, s2.`c8` AS `c3`, s2.`c9` AS `c4`, s2.`o` AS `o` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c0` AS `c5`, s3.`c1` AS `c6`, s3.`c2` AS `c7`, s3.`c3` AS `c8`, (CAST(s3.`c4` AS BIGINT) - CAST(1 AS BIGINT)) AS `c9`, s3.`o` AS `o` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3`, ROW_NUMBER() OVER (PARTITION BY s4.`c0` ORDER BY s4.`c1` ASC NULLS LAST) AS `c4`, ROW_NUMBER() OVER (ORDER BY s4.`c1` ASC NULLS LAST) AS `o` FROM (SELECT s5.`c0` AS `c0`, s5.`c1` AS `c1`, s5.`c2` AS `c2`, LEAD(s5.`c1`, 2, CAST(-1 AS BIGINT)) OVER (ORDER BY s5.`c1` DESC NULLS LAST) AS `c3` FROM (SELECT s6.`c0` AS `c0`, s6.`c1` AS `c1`, LAG(s6.`c1`, 1, CAST(NULL AS BIGINT)) OVER (PARTITION BY s6.`c0` ORDER BY s6.`c1` ASC NULLS FIRST) AS `c2` FROM (SELECT `g` AS `c0`, `x` AS `c1` FROM `w`) AS s6) AS s5) AS s4) AS s3) AS s2) AS s1 ORDER BY s1.`o` ASC NULLS LAST
